67	func parseModuleAddress(s string) (api.ModuleIdentifier, error) {
68		parts := strings.Split(s, "/")
69		if len(parts) != 3 {
70			return api.ModuleIdentifier{}, fmt.Errorf("%w: module address must be namespace/name/provider, got %q", ErrUsage, s)
71		}
72		id := api.ModuleIdentifier{Namespace: parts[0], Name: parts[1], Provider: parts[2]}
73		if err := id.Validate(); err != nil {
74			return api.ModuleIdentifier{}, fmt.Errorf("%w: %v", ErrUsage, err)
75		}
76		return id, nil
77	}
